{"command": "cd /home/zhaodan/work/NodeJsProjects/agent-hub-web && python3 - <<'EOF'
from pathlib import Path
p = Path('src/components/chat/ProcessTimeline.vue')
s = p.read_text()
s = s.replace("""import { ref } from 'vue'""", """import { computed, ref } from 'vue'""")
s = s.replace("""import type { ProcessItem } from '@/types'

defineProps<{
  items: ProcessItem[]
  busy?: boolean
  /** M5：正在处理的审批 id；多审批时只禁用对应卡片。 */
  resolvingApprovalId?: string | null
}>()

const emit = defineEmits<{
  approve: [id: string]
  reject: [id: string]
}>()

const open = ref(true)""", """import type { A2aProcess, ProcessItem } from '@/types'

const props = defineProps<{
  items: ProcessItem[]
  busy?: boolean
  /** M5：正在处理的审批 id；多审批时只禁用对应卡片。 */
  resolvingApprovalId?: string | null
  /** 本轮思考总时长；用于还原原型“思考 12s · 7 步 …”摘要。 */
  reasoningMs?: number
}>()

const emit = defineEmits<{
  approve: [id: string]
  reject: [id: string]
  'open-output': [item: A2aProcess]
}>()

const open = ref(true)

/** 原型摘要：思考时长 / 步骤数 / 远程智能体数 / 审批数；无数据项不显示。 */
const summary = computed(() => {
  const parts: string[] = []
  if (props.reasoningMs && props.reasoningMs > 0) {
    parts.push(`思考 ${Math.max(1, Math.round(props.reasoningMs / 1000))}s`)
  }
  const steps = props.items.filter((item) => item.kind !== 'notice').length
  if (steps > 0) parts.push(`${steps} 步`)
  const a2a = props.items.filter((item) => item.kind === 'a2a').length
  if (a2a > 0) parts.push(`${a2a} 个远程智能体`)
  const approvals = props.items.filter((item) => item.kind === 'approval').length
  if (approvals > 0) parts.push(`${approvals} 个审批`)
  return parts.length > 0 ? parts.join(' · ') : '执行过程'
})""")
s = s.replace("""        <span>执行过程 · {{ items.length }}</span>""", """        <span>{{ summary }}</span>""")
s = s.replace("""        <A2ACard v-else-if="item.kind === 'a2a'" :item="item" />""", """        <A2ACard
          v-else-if="item.kind === 'a2a'"
          :item="item"
          @open-output="emit('open-output', $event)"
        />""")
p.write_text(s)
print('ok')
EOF
grep -n "summary\|open-output\|reasoningMs" src/components/chat/ProcessTimeline.vue | head -12", "description": "过程摘要与输出事件"}

