function selectConversation(id: string): void {
  if (chat.state.streaming) chat.stop()
  mobileOpen.value = false
  if (route.name === 'chat') {
    void router.replace({ name: 'chat', query: { ...route.query, c: id } })
  } else {
    void router.push({ name: 'chat', query: { c: id } })
  }
}

